// Commander cinematic homepage installer.
// Run from your commander-hub folder:   node install-cinematic.js
// It only writes the 11 files listed below (no network, nothing else is touched),
// backs up your current app/page.tsx first, then checks every file it wrote.
const fs = require("fs");
const path = require("path");

const root = process.cwd();
const pkgPath = path.join(root, "package.json");
if (!fs.existsSync(pkgPath) || !/"next"/.test(fs.readFileSync(pkgPath, "utf8"))) {
  console.error("\nSTOP: this doesn't look like the commander-hub folder (no Next.js package.json here).");
  console.error("Open a terminal INSIDE commander-hub and run it again.\n");
  process.exit(1);
}

const FILES = {
 "app/cinematic.css": "/* Cinematic homepage — motion + hover styles. Everything here is optional\n   decoration, and all of it switches off for people who prefer reduced motion. */\n\n@keyframes cz-sweep {\n  to { transform: rotate(360deg); }\n}\n@keyframes cz-ping {\n  0%   { transform: scale(0.6); opacity: 0.95; }\n  100% { transform: scale(3);   opacity: 0; }\n}\n@keyframes cz-rise {\n  from { opacity: 0; transform: translateY(46px); }\n  to   { opacity: 1; transform: none; }\n}\n@keyframes cz-blink {\n  from { opacity: 1; }\n  to   { opacity: 0.25; }\n}\n\n.cz-sweep { animation: cz-sweep 8s linear infinite; }\n.cz-ping  { transform-box: fill-box; transform-origin: center; animation: cz-ping 3.2s ease-out infinite; }\n.cz-rise  { animation: cz-rise 0.95s cubic-bezier(0.2, 0.7, 0.2, 1) both; }\n.cz-blink { animation: cz-blink 1.2s ease-in-out infinite alternate; }\n\n.cz-d1 { animation-delay: 0.1s; }\n.cz-d2 { animation-delay: 0.28s; }\n.cz-d3 { animation-delay: 0.46s; }\n.cz-d4 { animation-delay: 0.64s; }\n.cz-d5 { animation-delay: 0.82s; }\n\n.cz-poster-art { transition: transform 0.6s cubic-bezier(0.2, 0.7, 0.2, 1); }\n.cz-poster:hover .cz-poster-art { transform: scale(1.04); }\n\n.cz-podium-link { transition: transform 0.25s ease, border-color 0.25s ease; }\n.cz-podium-link:hover { transform: translateY(-4px); }\n\n@media (prefers-reduced-motion: reduce) {\n  .cz-sweep, .cz-ping, .cz-rise, .cz-blink { animation: none !important; }\n  .cz-poster-art, .cz-podium-link { transition: none !important; }\n  .cz-poster:hover .cz-poster-art, .cz-podium-link:hover { transform: none !important; }\n}\n",
 "app/page.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { FolderOpen, Video, Info, Mail, ArrowUpRight } from \"lucide-react\";\nimport { C } from \"@/lib/theme\";\nimport LiveBanner from \"@/components/LiveBanner\";\nimport NewsFeed from \"@/components/NewsFeed\";\nimport YouTubeSection from \"@/components/YouTubeSection\";\nimport FadeIn from \"@/components/FadeIn\";\nimport CinematicHero from \"@/components/home/CinematicHero\";\nimport FactsStrip from \"@/components/home/FactsStrip\";\nimport WaysIn from \"@/components/home/WaysIn\";\nimport FrontLine from \"@/components/home/FrontLine\";\nimport JoinBanner from \"@/components/home/JoinBanner\";\nimport { useHomeData } from \"@/components/home/useHomeData\";\nimport { useLanguage } from \"@/lib/i18n/LanguageContext\";\nimport { HOME_TEXT } from \"@/components/home/homeText\";\nimport \"@/app/animations.css\";\n\nconst CORNERS = [\n  \"top-2 left-2 border-t border-l\",\n  \"top-2 right-2 border-t border-r\",\n  \"bottom-2 left-2 border-b border-l\",\n  \"bottom-2 right-2 border-b border-r\",\n];\n\nexport default function Home() {\n  const { t, locale } = useLanguage();\n  const text = HOME_TEXT[locale === \"ar\" ? \"ar\" : \"en\"];\n  const data = useHomeData(); // one shared fetch for the hero, the radar and the podium\n\n  // The ladder, replays and tournaments are covered by \"Three ways in\";\n  // these are the remaining sectors.\n  const MORE = [\n    { icon: FolderOpen, title: t(\"home.opsDownloadsTitle\"), description: t(\"home.opsDownloadsDesc\"), href: \"/downloads\", tag: t(\"home.opsDownloadsTag\") },\n    { icon: Video, title: t(\"home.opsVideosTitle\"), description: t(\"home.opsVideosDesc\"), href: \"/videos\", tag: t(\"home.opsVideosTag\") },\n    { icon: Info, title: t(\"home.opsAboutTitle\"), description: t(\"home.opsAboutDesc\"), href: \"/about\", tag: t(\"home.opsAboutTag\") },\n    { icon: Mail, title: t(\"home.opsContactTitle\"), description: t(\"home.opsContactDesc\"), href: \"/contact\", tag: t(\"home.opsContactTag\") },\n  ];\n\n  return (\n    <main className=\"min-h-screen w-full\" style={{ background: C.void }}>\n      <CinematicHero data={data} />\n      <FactsStrip />\n\n      <div className=\"mx-auto max-w-6xl px-6 md:px-10\">\n        <FadeIn>\n          <div className=\"mt-10 empty:hidden\">\n            <LiveBanner />\n          </div>\n        </FadeIn>\n      </div>\n\n      <WaysIn />\n      <FrontLine data={data} />\n\n      <div className=\"mx-auto max-w-6xl px-6 pb-16 md:px-10\">\n        <FadeIn>\n          <div className=\"mb-4 flex items-center justify-between\">\n            <h2 className=\"cz-display text-2xl uppercase\" style={{ fontWeight: 600 }}>\n              {t(\"home.latest\")}\n            </h2>\n            <Link href=\"/news\" className=\"text-xs uppercase tracking-widest\" style={{ color: C.amber }}>\n              {t(\"home.viewAll\")}\n            </Link>\n          </div>\n          <NewsFeed limit={3} />\n        </FadeIn>\n\n        <FadeIn>\n          <YouTubeSection />\n        </FadeIn>\n\n        <FadeIn>\n          <div className=\"mt-16\">\n            <div className=\"text-[11px] uppercase tracking-[0.24em]\" style={{ color: C.radar }}>\n              {text.exploreEyebrow}\n            </div>\n            <section className=\"mt-4 grid gap-5 sm:grid-cols-2 lg:grid-cols-4\">\n              {MORE.map((item) => {\n                const Icon = item.icon;\n                return (\n                  <Link\n                    key={item.href}\n                    href={item.href}\n                    className=\"cz-card cz-hover-lift group relative block p-5\"\n                    style={{ background: C.panel, border: `1px solid ${C.line}` }}\n                  >\n                    {CORNERS.map((pos) => (\n                      <span\n                        key={pos}\n                        aria-hidden=\"true\"\n                        className={`cz-bracket pointer-events-none absolute h-3 w-3 opacity-0 transition-opacity duration-300 group-hover:opacity-100 ${pos}`}\n                        style={{ borderColor: C.amber }}\n                      />\n                    ))}\n                    <div className=\"mb-5 text-[10px] uppercase tracking-widest\" style={{ color: C.muted }}>\n                      {item.tag}\n                    </div>\n                    <Icon size={22} style={{ color: C.amber }} />\n                    <h3 className=\"mt-4 text-base\" style={{ color: C.paper, fontWeight: 500 }}>\n                      {item.title}\n                    </h3>\n                    <p className=\"mt-2 text-xs\" style={{ color: C.muted }}>\n                      {item.description}\n                    </p>\n                    <div\n                      className=\"mt-5 flex items-center justify-between pt-3 text-xs uppercase tracking-widest\"\n                      style={{ borderTop: `1px solid ${C.line}`, color: C.amber }}\n                    >\n                      <span>{t(\"common.enter\")}</span>\n                      <ArrowUpRight size={14} />\n                    </div>\n                  </Link>\n                );\n              })}\n            </section>\n          </div>\n        </FadeIn>\n\n        <FadeIn>\n          <Link\n            href=\"/donate\"\n            className=\"cz-card cz-hover-lift group relative mt-10 block p-6\"\n            style={{ background: C.panel, border: `1px solid ${C.radar}` }}\n          >\n            <div className=\"flex flex-col gap-4 md:flex-row md:items-center md:justify-between\">\n              <div>\n                <span className=\"text-[10px] uppercase tracking-widest\" style={{ color: C.radar }}>\n                  {t(\"home.supportUs\")}\n                </span>\n                <h3 className=\"cz-display mt-1 text-xl uppercase\" style={{ color: C.paper, fontWeight: 600 }}>\n                  {t(\"home.donateTitle\")}\n                </h3>\n                <p className=\"mt-2 text-xs\" style={{ color: C.muted }}>\n                  {t(\"home.donateDesc\")}\n                </p>\n              </div>\n              <span\n                className=\"inline-flex shrink-0 items-center gap-2 px-6 py-3 text-xs uppercase tracking-widest\"\n                style={{ border: `1px solid ${C.radar}`, color: C.radar }}\n              >\n                {t(\"home.donate\")}\n                <ArrowUpRight size={14} />\n              </span>\n            </div>\n          </Link>\n        </FadeIn>\n      </div>\n\n      <JoinBanner />\n    </main>\n  );\n}\n",
 "components/home/homeText.ts": "// All new homepage copy, in both languages, kept in one place.\n// (Arabic was drafted to match the tone of your existing translations —\n// worth a quick read-through by a native speaker before launch.)\nexport const HOME_TEXT = {\n  en: {\n    heroEyebrow: \"Generals Zero Hour · Ranked community\",\n    heroLine1: \"Commander\",\n    heroJoin: \"Join\",\n    heroTag: \"COM | TEAM\",\n    heroSub: \"Ranked ladders, a replay library and tournaments for the people who still play Zero Hour.\",\n    joinClan: \"Join our clan\",\n    watchLatest: \"Watch the latest video\",\n    statPlayers: \"Players\",\n    statMatches: \"Matches\",\n    statReplays: \"Replays\",\n    barLeft: \"Field report\",\n    barRight: \"Broadcasting\",\n    barScroll: \"Scroll\",\n    barLangs: \"English · العربية\",\n    facts: [\"2v2 · 3v3 · 4v4 ladder\", \"FFA ladder\", \"Replay library\", \"Tournaments\", \"Maps and mods\", \"English and Arabic\"],\n    waysEyebrow: \"Start here\",\n    waysTitle: \"Three ways in\",\n    ways: [\n      { n: \"01\", title: \"Play ranked\", desc: \"Team and FFA ladders with ratings that reset every season.\", cta: \"Open the ladder\" },\n      { n: \"02\", title: \"Study replays\", desc: \"Download professional Zero Hour matches.\", cta: \"Browse the library\" },\n      { n: \"03\", title: \"Compete\", desc: \"Events, rankings and winners.\", cta: \"See tournaments\" },\n    ],\n    frontEyebrow: \"Current standings\",\n    frontTitle1: \"Top\",\n    frontTitle2: \"commanders\",\n    team: \"Team\",\n    ffa: \"FFA\",\n    fullBoard: \"Full leaderboard\",\n    frontEmpty: \"No ranked players yet this season.\",\n    joinEyebrow: \"Recruiting now\",\n    joinTitle1: \"Your seat\",\n    joinTitle2: \"is waiting.\",\n    joinText: \"Looking to compete, contribute, or help run the clan? Apply now and we'll get back to you on Discord.\",\n    apply: \"Apply now\",\n    discord: \"Join the Discord\",\n    exploreEyebrow: \"Explore\",\n  },\n  ar: {\n    heroEyebrow: \"جنرالات الساعة الصفر · مجتمع تنافسي\",\n    heroLine1: \"Commander\",\n    heroJoin: \"انضم إلى\",\n    heroTag: \"COM | TEAM\",\n    heroSub: \"ترتيب تنافسي ومكتبة إعادات وبطولات لمن لا يزال يلعب جنرالات الساعة الصفر.\",\n    joinClan: \"انضم إلى الكلان\",\n    watchLatest: \"شاهد آخر فيديو\",\n    statPlayers: \"لاعبون\",\n    statMatches: \"مباريات\",\n    statReplays: \"إعادات\",\n    barLeft: \"تقرير ميداني\",\n    barRight: \"بث مباشر\",\n    barScroll: \"مرّر للأسفل\",\n    barLangs: \"English · العربية\",\n    facts: [\"تصنيف 2v2 · 3v3 · 4v4\", \"تصنيف FFA\", \"مكتبة الإعادات\", \"البطولات\", \"الخرائط والتعديلات\", \"الإنجليزية والعربية\"],\n    waysEyebrow: \"ابدأ من هنا\",\n    waysTitle: \"ثلاث طرق للانضمام\",\n    ways: [\n      { n: \"01\", title: \"العب تنافسياً\", desc: \"تصنيفات الفرق والـ FFA مع تقييمات تُعاد كل موسم.\", cta: \"افتح الترتيب\" },\n      { n: \"02\", title: \"ادرس الإعادات\", desc: \"حمّل مباريات احترافية من Zero Hour.\", cta: \"تصفح المكتبة\" },\n      { n: \"03\", title: \"نافس\", desc: \"فعاليات وترتيب وفائزون.\", cta: \"شاهد البطولات\" },\n    ],\n    frontEyebrow: \"الترتيب الحالي\",\n    frontTitle1: \"أفضل\",\n    frontTitle2: \"القادة\",\n    team: \"الفرق\",\n    ffa: \"FFA\",\n    fullBoard: \"لوحة الترتيب الكاملة\",\n    frontEmpty: \"لا يوجد لاعبون مصنَّفون بعد هذا الموسم.\",\n    joinEyebrow: \"التجنيد مفتوح\",\n    joinTitle1: \"مقعدك\",\n    joinTitle2: \"ينتظرك.\",\n    joinText: \"تريد المنافسة أو المساهمة أو المساعدة في إدارة الكلان؟ قدّم الآن وسنتواصل معك على ديسكورد.\",\n    apply: \"قدّم الآن\",\n    discord: \"انضم إلى ديسكورد\",\n    exploreEyebrow: \"استكشف\",\n  },\n} as const;\n\nexport type HomeLocale = keyof typeof HOME_TEXT;\n",
 "components/home/useHomeData.ts": "\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport { createClient } from \"@/lib/supabase/client\";\n\nexport type Leader = {\n  name: string;\n  rating: number;\n  wins: number;\n  losses: number;\n  avatarUrl: string | null;\n};\n\nexport type HomeData = {\n  loaded: boolean;\n  members: number;\n  matches: number;\n  replays: number;\n  teamTop: Leader[];\n  ffaTop: Leader[];\n};\n\nconst EMPTY: HomeData = { loaded: false, members: 0, matches: 0, replays: 0, teamTop: [], ffaTop: [] };\n\n// Same rule as the leaderboard: you need this many matches to hold a rank.\nconst MIN_MATCHES_FOR_RANK = 3;\n\ntype ProfileRow = { username: string; avatar_url: string | null; rating_team: number | null; rating_ffa: number | null; banned: boolean | null };\ntype GuestRow = { name: string; rating_team: number | null; rating_ffa: number | null };\ntype MatchRow = { participants: string[]; winners: string[]; mode: string; replay_url: string | null };\ntype Info = { team: number; ffa: number; avatar: string | null; banned: boolean };\n\n/**\n * One shared fetch for everything the homepage's live numbers need:\n * counts for the hero, and the top three per ladder for the radar and the podium.\n */\nexport function useHomeData(): HomeData {\n  const [data, setData] = useState<HomeData>(EMPTY);\n\n  useEffect(() => {\n    const supabase = createClient();\n    let cancelled = false;\n\n    async function load() {\n      const [profilesRes, guestsRes, matchesRes] = await Promise.all([\n        supabase.from(\"profiles\").select(\"username, avatar_url, rating_team, rating_ffa, banned\"),\n        supabase.from(\"guest_ratings\").select(\"name, rating_team, rating_ffa\"),\n        supabase.from(\"matches\").select(\"participants, winners, mode, replay_url\"),\n      ]);\n\n      const profiles = (profilesRes.data ?? []) as ProfileRow[];\n      const guests = (guestsRes.data ?? []) as GuestRow[];\n      const matches = (matchesRes.data ?? []) as MatchRow[];\n\n      const info = new Map<string, Info>();\n      for (const g of guests) {\n        info.set(g.name, { team: g.rating_team ?? 1000, ffa: g.rating_ffa ?? 1000, avatar: null, banned: false });\n      }\n      for (const p of profiles) {\n        info.set(p.username, {\n          team: p.rating_team ?? 1000,\n          ffa: p.rating_ffa ?? 1000,\n          avatar: p.avatar_url,\n          banned: !!p.banned,\n        });\n      }\n\n      function top(teamView: boolean): Leader[] {\n        const stats = new Map<string, { w: number; l: number }>();\n        for (const m of matches) {\n          const isFfa = m.mode === \"ffa\";\n          if (teamView ? isFfa : !isFfa) continue;\n          for (const name of m.participants) {\n            const row = stats.get(name) ?? { w: 0, l: 0 };\n            if (m.winners.includes(name)) row.w += 1;\n            else row.l += 1;\n            stats.set(name, row);\n          }\n        }\n\n        return Array.from(stats.entries())\n          .filter(([name, s]) => s.w + s.l >= MIN_MATCHES_FOR_RANK && !info.get(name)?.banned)\n          .map(([name, s]) => ({\n            name,\n            rating: (teamView ? info.get(name)?.team : info.get(name)?.ffa) ?? 1000,\n            wins: s.w,\n            losses: s.l,\n            avatarUrl: info.get(name)?.avatar ?? null,\n          }))\n          .sort((a, b) => b.rating - a.rating || a.name.localeCompare(b.name))\n          .slice(0, 3);\n      }\n\n      if (!cancelled) {\n        setData({\n          loaded: true,\n          members: profiles.filter((p) => !p.banned).length,\n          matches: matches.length,\n          replays: matches.filter((m) => !!m.replay_url).length,\n          teamTop: top(true),\n          ffaTop: top(false),\n        });\n      }\n    }\n\n    load().catch(() => {\n      if (!cancelled) setData({ ...EMPTY, loaded: true });\n    });\n\n    return () => {\n      cancelled = true;\n    };\n  }, []);\n\n  return data;\n}\n",
 "components/home/RadarScope.tsx": "\"use client\";\n\nimport { useMemo } from \"react\";\nimport { C } from \"@/lib/theme\";\n\nexport type RadarLeader = { name: string; rating: number };\n\ntype Props = {\n  /** Unique per instance on a page (used for SVG ids). */\n  uid: string;\n  /** Top players, rank 1 first. Without them the radar is purely decorative. */\n  leaders?: RadarLeader[];\n  /** Hide from screen readers (use for background art). */\n  decorative?: boolean;\n};\n\nconst MONO = \"var(--font-mono), ui-monospace, monospace\";\n\n// Fixed blip positions (in the 600x600 scope) for ranks 1, 2 and 3.\nconst LEADER_SPOTS = [\n  { x: 352, y: 206 },\n  { x: 214, y: 334 },\n  { x: 412, y: 384 },\n];\nconst MINOR_BLIPS: [number, number][] = [\n  [180, 200], [262, 146], [436, 282], [332, 478], [148, 402], [472, 172], [384, 118], [240, 444],\n];\n\n// A wobbly closed curve — stacked together they read as topographic contours.\nfunction contourPath(k: number, base: number, ox = 330, oy = 280): string {\n  const pts: string[] = [];\n  for (let t = 0; t < 360; t += 4) {\n    const a = (t * Math.PI) / 180;\n    const r = base + 14 * Math.sin(3 * a + k) + 8 * Math.sin(5 * a + 2 * k) + 5 * Math.sin(7 * a - k);\n    pts.push(`${(ox + r * Math.cos(a)).toFixed(1)},${(oy + r * Math.sin(a)).toFixed(1)}`);\n  }\n  return `M${pts.join(\" L\")} Z`;\n}\n\nexport default function RadarScope({ uid, leaders = [], decorative = false }: Props) {\n  const contours = useMemo(() => [40, 78, 116, 154, 192, 230].map((base, k) => contourPath(k, base)), []);\n  const ticks = useMemo(() => Array.from({ length: 72 }, (_, i) => i * 5), []);\n  const ringText = \"GENERALS ZERO HOUR · COMMANDER · RANKED LADDER · \".repeat(2);\n\n  const shown = leaders.slice(0, 3);\n  const label =\n    shown.length > 0\n      ? `Radar scope showing the top commanders: ${shown.map((l) => `${l.name} ${l.rating}`).join(\", \")}`\n      : \"Decorative radar scope\";\n\n  return (\n    <div className=\"relative w-full\" style={{ aspectRatio: \"1 / 1\" }}>\n      <svg\n        xmlns=\"http://www.w3.org/2000/svg\"\n        viewBox=\"-30 -30 660 660\"\n        width=\"100%\"\n        height=\"100%\"\n        role={decorative ? undefined : \"img\"}\n        aria-label={decorative ? undefined : label}\n        aria-hidden={decorative ? true : undefined}\n        style={{ display: \"block\", overflow: \"visible\" }}\n      >\n        <defs>\n          <radialGradient id={`${uid}-glow`} cx=\"50%\" cy=\"50%\" r=\"50%\">\n            <stop offset=\"0\" stopColor={C.radar} stopOpacity=\"0.22\" />\n            <stop offset=\"1\" stopColor={C.radar} stopOpacity=\"0\" />\n          </radialGradient>\n          <path id={`${uid}-ring`} d=\"M300,300 m-314,0 a314,314 0 1,1 628,0 a314,314 0 1,1 -628,0\" />\n        </defs>\n\n        <circle cx=\"300\" cy=\"300\" r=\"296\" fill={`url(#${uid}-glow)`} />\n\n        {contours.map((d, i) => (\n          <path key={i} d={d} fill=\"none\" stroke={C.radar} strokeOpacity=\"0.17\" strokeWidth=\"1\" />\n        ))}\n\n        {[296, 236, 176, 116, 56].map((r) => (\n          <circle\n            key={r}\n            cx=\"300\"\n            cy=\"300\"\n            r={r}\n            fill=\"none\"\n            stroke={r === 296 ? C.radar : C.lineStrong}\n            strokeOpacity={r === 296 ? 0.55 : 1}\n            strokeWidth=\"1\"\n          />\n        ))}\n        <line x1=\"4\" y1=\"300\" x2=\"596\" y2=\"300\" stroke={C.lineStrong} />\n        <line x1=\"300\" y1=\"4\" x2=\"300\" y2=\"596\" stroke={C.lineStrong} />\n\n        {ticks.map((deg) => {\n          const major = deg % 30 === 0;\n          return (\n            <line\n              key={deg}\n              x1=\"300\"\n              y1=\"4\"\n              x2=\"300\"\n              y2={major ? 16 : 10}\n              stroke={C.radar}\n              strokeOpacity={major ? 0.7 : 0.28}\n              transform={`rotate(${deg} 300 300)`}\n            />\n          );\n        })}\n\n        {[\n          [\"N\", 300, -4],\n          [\"E\", 612, 304],\n          [\"S\", 300, 616],\n          [\"W\", -12, 304],\n        ].map(([t, x, y]) => (\n          <text key={String(t)} x={x} y={y} textAnchor=\"middle\" fontSize=\"12\" fontWeight=\"600\" fill={C.muted} style={{ fontFamily: MONO }}>\n            {t}\n          </text>\n        ))}\n\n        <text fontSize=\"10\" letterSpacing=\"9.2\" fill={C.muted} style={{ fontFamily: MONO }}>\n          <textPath href={`#${uid}-ring`}>{ringText}</textPath>\n        </text>\n\n        {shown.length === 3 && (\n          <polygon\n            points={LEADER_SPOTS.map((p) => `${p.x},${p.y}`).join(\" \")}\n            fill={C.amber}\n            fillOpacity=\"0.04\"\n            stroke={C.amber}\n            strokeOpacity=\"0.5\"\n            strokeDasharray=\"5 6\"\n          />\n        )}\n\n        {MINOR_BLIPS.map(([x, y]) => (\n          <circle key={`${x}-${y}`} cx={x} cy={y} r=\"3.5\" fill={C.radar} fillOpacity=\"0.85\" />\n        ))}\n\n        {(shown.length > 0 ? shown : LEADER_SPOTS.map(() => null)).map((leader, i) => {\n          const { x, y } = LEADER_SPOTS[i];\n          return (\n            <g key={i}>\n              <circle className=\"cz-ping\" style={{ animationDelay: `${i * 0.8}s` }} cx={x} cy={y} r=\"9\" fill=\"none\" stroke={C.amber} strokeWidth=\"1.5\" />\n              <circle cx={x} cy={y} r=\"6\" fill={C.amber} />\n              <circle cx={x} cy={y} r=\"11\" fill=\"none\" stroke={C.amber} strokeOpacity=\"0.45\" />\n              {leader && (\n                <>\n                  <line x1={x + 12} y1={y - 10} x2={x + 34} y2={y - 26} stroke={C.amber} strokeOpacity=\"0.6\" />\n                  <text x={x + 38} y={y - 27} fontSize=\"13\" fontWeight=\"700\" fill={C.paper} style={{ fontFamily: MONO }}>\n                    {leader.name.toUpperCase().slice(0, 12)}\n                  </text>\n                  <text x={x + 38} y={y - 12} fontSize=\"12\" fill={C.amber} style={{ fontFamily: MONO }}>\n                    {leader.rating}\n                  </text>\n                </>\n              )}\n            </g>\n          );\n        })}\n      </svg>\n\n      {/* The rotating sweep beam, clipped to the scope's outer ring. */}\n      <div\n        aria-hidden=\"true\"\n        className=\"cz-sweep\"\n        style={{\n          position: \"absolute\",\n          left: \"5.15%\",\n          top: \"5.15%\",\n          width: \"89.7%\",\n          height: \"89.7%\",\n          borderRadius: \"50%\",\n          background:\n            \"conic-gradient(from 0deg, rgba(143,191,79,0) 0deg, rgba(143,191,79,0) 296deg, rgba(143,191,79,0.30) 350deg, rgba(143,191,79,0.65) 360deg)\",\n        }}\n      />\n    </div>\n  );\n}\n",
 "components/home/PosterArt.tsx": "import { C } from \"@/lib/theme\";\n\nconst DISPLAY = \"var(--font-display), 'Oswald', sans-serif\";\n\nfunction Frame({ id, glow = C.amber, children }: { id: string; glow?: string; children: React.ReactNode }) {\n  return (\n    <svg\n      xmlns=\"http://www.w3.org/2000/svg\"\n      viewBox=\"0 0 400 300\"\n      width=\"100%\"\n      height=\"100%\"\n      preserveAspectRatio=\"xMidYMid slice\"\n      aria-hidden=\"true\"\n      style={{ display: \"block\" }}\n    >\n      <defs>\n        <radialGradient id={id} cx=\"50%\" cy=\"55%\" r=\"65%\">\n          <stop offset=\"0\" stopColor={glow} stopOpacity=\"0.2\" />\n          <stop offset=\"1\" stopColor={glow} stopOpacity=\"0\" />\n        </radialGradient>\n      </defs>\n      <rect width=\"400\" height=\"300\" fill={C.panel} />\n      <rect width=\"400\" height=\"300\" fill={`url(#${id})`} />\n      {children}\n    </svg>\n  );\n}\n\n/** A podium on a grid — \"play ranked\". */\nexport function LadderArt() {\n  const bars = [\n    { x: 70, h: 110, n: \"2\", c: \"#C0C0C0\", top: false },\n    { x: 155, h: 160, n: \"1\", c: C.amber, top: true },\n    { x: 240, h: 110, n: \"3\", c: \"#CD7F32\", top: false },\n  ];\n  return (\n    <Frame id=\"art-ladder\">\n      {Array.from({ length: 17 }, (_, i) => (\n        <line key={`v${i}`} x1={i * 25} y1=\"0\" x2={i * 25} y2=\"300\" stroke={C.line} />\n      ))}\n      {Array.from({ length: 13 }, (_, i) => (\n        <line key={`h${i}`} x1=\"0\" y1={i * 25} x2=\"400\" y2={i * 25} stroke={C.line} />\n      ))}\n      {bars.map((b) => {\n        const y = 250 - b.h;\n        return (\n          <g key={b.n}>\n            <rect x={b.x} y={y} width=\"90\" height={b.h} fill={b.top ? \"rgba(232,166,61,0.14)\" : C.panelHover} stroke={b.c} strokeWidth={b.top ? 2 : 1} />\n            <text x={b.x + 45} y={y + 52} textAnchor=\"middle\" fontSize=\"48\" fontWeight=\"700\" fill={b.c} style={{ fontFamily: DISPLAY }}>\n              {b.n}\n            </text>\n            <circle cx={b.x + 45} cy={y - 22} r=\"14\" fill=\"none\" stroke={b.c} strokeWidth=\"2\" />\n          </g>\n        );\n      })}\n      <line x1=\"40\" y1=\"250\" x2=\"360\" y2=\"250\" stroke={C.amber} strokeWidth=\"2\" />\n    </Frame>\n  );\n}\n\n/** A film strip with a playhead and waveform — \"study replays\". */\nexport function ReplayArt() {\n  return (\n    <Frame id=\"art-replay\" glow={C.radar}>\n      {Array.from({ length: 6 }, (_, i) => {\n        const x = 24 + i * 60;\n        const active = i === 3;\n        return (\n          <g key={i}>\n            <rect x={x} y=\"70\" width=\"52\" height=\"72\" fill={active ? \"rgba(232,166,61,0.12)\" : C.panelHover} stroke={active ? C.amber : C.lineStrong} strokeWidth={active ? 2 : 1} />\n            {[60, 146].map((hy) => (\n              <g key={hy}>\n                <rect x={x + 6} y={hy} width=\"8\" height=\"6\" fill={C.lineStrong} />\n                <rect x={x + 22} y={hy} width=\"8\" height=\"6\" fill={C.lineStrong} />\n                <rect x={x + 38} y={hy} width=\"8\" height=\"6\" fill={C.lineStrong} />\n              </g>\n            ))}\n            <path d={`M${x + 10} 120 l10 -22 8 14 6 -8 8 16z`} fill=\"none\" stroke={active ? C.amber : C.radar} strokeOpacity=\"0.8\" strokeWidth=\"1.5\" />\n          </g>\n        );\n      })}\n      <line x1=\"24\" y1=\"190\" x2=\"376\" y2=\"190\" stroke={C.lineStrong} strokeWidth=\"2\" />\n      <line x1=\"24\" y1=\"190\" x2=\"204\" y2=\"190\" stroke={C.amber} strokeWidth=\"2\" />\n      {Array.from({ length: 45 }, (_, i) => {\n        const x = 24 + i * 8;\n        const h = 6 + Math.abs(Math.sin(i * 0.7) * 18) + Math.abs(Math.sin(i * 0.23) * 10);\n        const played = x < 204;\n        return (\n          <line key={i} x1={x} y1={248 - h / 2} x2={x} y2={248 + h / 2} stroke={played ? C.amber : C.muted} strokeWidth=\"3\" strokeOpacity={played ? 0.9 : 0.55} />\n        );\n      })}\n      <line x1=\"204\" y1=\"44\" x2=\"204\" y2=\"276\" stroke={C.amber} strokeWidth=\"2\" />\n      <path d=\"M194 38 h20 l-10 12z\" fill={C.amber} />\n    </Frame>\n  );\n}\n\n/** A tournament bracket with the winning path lit — \"compete\". */\nexport function BracketArt() {\n  const slots = Array.from({ length: 8 }, (_, i) => 40 + i * 30);\n  const r2 = [0, 1, 2, 3].map((i) => (slots[2 * i] + slots[2 * i + 1]) / 2);\n  const r3 = [0, 1].map((i) => (r2[2 * i] + r2[2 * i + 1]) / 2);\n  const fin = (r3[0] + r3[1]) / 2;\n\n  const slot = (x: number, y: number, w: number, hl: boolean, key: string) => (\n    <rect key={key} x={x} y={y - 9} width={w} height=\"18\" fill={C.panelHover} stroke={hl ? C.amber : C.lineStrong} strokeWidth={hl ? 1.6 : 1} />\n  );\n  const conn = (x1: number, y1: number, x2: number, y2: number, hl: boolean, key: string) => (\n    <polyline key={key} points={`${x1},${y1} ${(x1 + x2) / 2},${y1} ${(x1 + x2) / 2},${y2} ${x2},${y2}`} fill=\"none\" stroke={hl ? C.amber : C.lineStrong} strokeWidth={hl ? 1.6 : 1} />\n  );\n\n  return (\n    <Frame id=\"art-bracket\">\n      {slots.map((y, i) => slot(30, y, 76, i === 0, `a${i}`))}\n      {r2.map((y, i) => slot(140, y, 76, i === 0, `b${i}`))}\n      {r3.map((y, i) => slot(250, y, 76, i === 0, `c${i}`))}\n      {slot(336, fin, 54, true, \"fin\")}\n      {[0, 1, 2, 3].flatMap((i) => [conn(106, slots[2 * i], 140, r2[i], i === 0, `c1-${i}`), conn(106, slots[2 * i + 1], 140, r2[i], false, `c2-${i}`)])}\n      {[0, 1].flatMap((i) => [conn(216, r2[2 * i], 250, r3[i], i === 0, `d1-${i}`), conn(216, r2[2 * i + 1], 250, r3[i], false, `d2-${i}`)])}\n      {conn(326, r3[0], 336, fin, true, \"e1\")}\n      {conn(326, r3[1], 336, fin, false, \"e2\")}\n      <g transform={`translate(351 ${fin - 30})`} fill=\"none\" stroke={C.amber} strokeWidth=\"1.6\" strokeLinecap=\"round\">\n        <path d=\"M6 14H3.5a2 2 0 0 1 0-4H6\" />\n        <path d=\"M18 14h2.5a2 2 0 0 0 0-4H18\" />\n        <path d=\"M6 8h12v5a6 6 0 0 1-12 0z\" />\n        <path d=\"M9 21h6\" />\n      </g>\n    </Frame>\n  );\n}\n",
 "components/home/CinematicHero.tsx": "\"use client\";\n\nimport { ArrowUpRight, Play, Radio } from \"lucide-react\";\nimport { C, DISCORD_URL, YOUTUBE_URL } from \"@/lib/theme\";\nimport { useLanguage } from \"@/lib/i18n/LanguageContext\";\nimport RadarScope from \"./RadarScope\";\nimport { HOME_TEXT } from \"./homeText\";\nimport type { HomeData } from \"./useHomeData\";\nimport \"@/app/cinematic.css\";\n\nconst GRID = \"linear-gradient(rgba(39,43,30,0.55) 1px, transparent 1px), linear-gradient(90deg, rgba(39,43,30,0.55) 1px, transparent 1px)\";\n\n// Where the banner image sits in its frame. If the important part of your\n// banner is cut off, change this (e.g. \"left center\", \"center top\", \"30% 50%\").\nconst BANNER_POSITION = \"center center\";\n\nconst CORNERS = [\n  \"top-2 left-2 border-t border-l\",\n  \"top-2 right-2 border-t border-r\",\n  \"bottom-2 left-2 border-b border-l\",\n  \"bottom-2 right-2 border-b border-r\",\n];\n\nexport default function CinematicHero({ data }: { data: HomeData }) {\n  const { locale } = useLanguage();\n  const text = HOME_TEXT[locale === \"ar\" ? \"ar\" : \"en\"];\n  const rtl = locale === \"ar\";\n\n  const leaders = data.teamTop.map((l) => ({ name: l.name, rating: l.rating }));\n\n  // Only show a stat once it has something to show — \"0 matches\" would hurt more than it helps.\n  const stats = [\n    { value: data.members, label: text.statPlayers },\n    { value: data.matches, label: text.statMatches },\n    { value: data.replays, label: text.statReplays },\n  ].filter((s) => s.value > 0);\n\n  const barStyle = {\n    background: \"#000\",\n    color: C.muted,\n    fontSize: 10,\n    letterSpacing: \"0.22em\",\n    textTransform: \"uppercase\" as const,\n  };\n\n  return (\n    <section\n      className=\"relative overflow-hidden\"\n      style={{\n        backgroundColor: C.void,\n        backgroundImage: `radial-gradient(ellipse 60% 70% at ${rtl ? \"22%\" : \"78%\"} 45%, rgba(143,191,79,0.13), transparent 62%), radial-gradient(ellipse 50% 50% at ${rtl ? \"10%\" : \"90%\"} 10%, rgba(232,166,61,0.14), transparent 60%), ${GRID}`,\n        backgroundSize: \"100% 100%, 100% 100%, 56px 56px, 56px 56px\",\n      }}\n    >\n      {/* Radar — on the right, large and cropped (large screens) */}\n      <div\n        className=\"pointer-events-none absolute hidden lg:block\"\n        style={{ insetInlineEnd: \"-14%\", top: 92, width: \"min(52vw, 760px)\", zIndex: 1 }}\n      >\n        <RadarScope uid=\"hero\" leaders={leaders} />\n      </div>\n\n      {/* Keeps the text readable where it meets the radar */}\n      <div\n        aria-hidden=\"true\"\n        className=\"absolute inset-0\"\n        style={{\n          zIndex: 1,\n          background: `linear-gradient(${rtl ? \"270deg\" : \"90deg\"}, ${C.void} 0%, rgba(10,12,8,0.7) 45%, rgba(10,12,8,0) 72%), linear-gradient(0deg, ${C.void} 0%, rgba(10,12,8,0) 30%)`,\n        }}\n      />\n\n      {/* Cinematic letterbox bars */}\n      <div className=\"absolute inset-x-0 top-0 flex h-[38px] items-center justify-between px-6 md:px-16\" style={{ ...barStyle, zIndex: 3 }}>\n        <span>{text.barLeft}</span>\n        <span className=\"inline-flex items-center gap-2\">\n          <span className=\"cz-blink inline-block h-1.5 w-1.5 rounded-full\" style={{ background: C.radar }} />\n          {text.barRight}\n        </span>\n      </div>\n      <div className=\"absolute inset-x-0 bottom-0 flex h-[38px] items-center justify-between px-6 md:px-16\" style={{ ...barStyle, zIndex: 3 }}>\n        <span>{text.barScroll}</span>\n        <span>{text.barLangs}</span>\n      </div>\n\n      <div className=\"relative mx-auto max-w-[1312px] px-6 pb-24 pt-[64px] md:px-16 md:pt-[110px]\" style={{ zIndex: 2, minHeight: 760 }}>\n        <div className=\"flex flex-col gap-8 md:flex-row md:items-start md:gap-12\">\n          {/* Banner image — on the left */}\n          <figure\n            className=\"cz-rise cz-d1 relative m-0 w-full shrink-0 overflow-hidden md:w-[280px] lg:w-[340px]\"\n            style={{ border: `1px solid ${C.lineStrong}`, background: C.panel }}\n          >\n            <div className=\"aspect-[16/9] md:aspect-[3/4]\">\n              {/* eslint-disable-next-line @next/next/no-img-element */}\n              <img\n                src=\"/images/banner.png\"\n                alt=\"\"\n                className=\"h-full w-full object-cover\"\n                style={{ objectPosition: BANNER_POSITION }}\n              />\n            </div>\n            <div\n              aria-hidden=\"true\"\n              className=\"absolute inset-0\"\n              style={{ background: \"linear-gradient(180deg, rgba(10,12,8,0.15) 0%, rgba(10,12,8,0) 40%, rgba(10,12,8,0.7) 100%)\" }}\n            />\n            {CORNERS.map((pos) => (\n              <span key={pos} aria-hidden=\"true\" className={`pointer-events-none absolute h-3 w-3 ${pos}`} style={{ borderColor: C.amber }} />\n            ))}\n          </figure>\n\n          {/* Text */}\n          <div className=\"min-w-0 flex-1\">\n            <div className=\"cz-rise cz-d1 flex items-center gap-2.5 text-xs uppercase tracking-[0.24em]\" style={{ color: C.radar }}>\n              <Radio size={14} />\n              <span>{text.heroEyebrow}</span>\n            </div>\n\n            <h1 className=\"cz-display mt-5 uppercase\" style={{ fontWeight: 700, lineHeight: 0.9 }}>\n              <span className=\"cz-rise cz-d2 block\" style={{ fontSize: \"clamp(56px, 8.6vw, 124px)\", color: C.paper }}>\n                {text.heroLine1}\n              </span>\n              <span\n                className=\"cz-rise cz-d3 mt-3 block\"\n                style={{ fontSize: \"clamp(28px, 4.4vw, 64px)\", lineHeight: 1, letterSpacing: \"0.01em\", color: C.amber }}\n              >\n                {text.heroJoin} <bdi dir=\"ltr\">{text.heroTag}</bdi>\n              </span>\n            </h1>\n\n            <p className=\"cz-rise cz-d4 mt-7 max-w-[500px] text-base leading-relaxed md:text-lg\" style={{ color: C.paper }}>\n              {text.heroSub}\n            </p>\n\n            <div className=\"cz-rise cz-d5 mt-8 flex flex-wrap items-center gap-x-7 gap-y-3\">\n              <a\n                href={DISCORD_URL}\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                className=\"inline-flex min-h-[58px] items-center gap-2.5 px-8 text-sm font-bold uppercase tracking-[0.12em]\"\n                style={{ background: C.amber, color: C.void, boxShadow: \"0 0 34px rgba(232,166,61,0.32)\" }}\n              >\n                {text.joinClan}\n                <ArrowUpRight size={16} strokeWidth={2.5} />\n              </a>\n              <a\n                href={YOUTUBE_URL}\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                className=\"inline-flex min-h-[44px] items-center gap-3 text-[13px] font-semibold uppercase tracking-[0.1em]\"\n                style={{ color: C.paper }}\n              >\n                <span className=\"inline-flex h-[38px] w-[38px] items-center justify-center rounded-full\" style={{ background: \"#CC0000\" }}>\n                  <Play size={14} color=\"#fff\" fill=\"#fff\" />\n                </span>\n                {text.watchLatest}\n              </a>\n            </div>\n\n            {stats.length > 0 && (\n              <div\n                className=\"cz-rise cz-d5 mt-14 flex max-w-[640px] flex-wrap gap-x-0 gap-y-4 pt-6 md:mt-16\"\n                style={{ borderTop: `1px solid ${C.lineStrong}` }}\n              >\n                {stats.map((s) => (\n                  <div key={s.label} className=\"flex-1\" style={{ minWidth: 110, paddingInlineEnd: 24 }}>\n                    <div className=\"cz-display\" style={{ fontSize: \"clamp(40px, 5vw, 60px)\", fontWeight: 700, lineHeight: 1, color: C.amber }}>\n                      {s.value.toLocaleString(\"en\")}\n                    </div>\n                    <div className=\"mt-2 text-[11px] uppercase tracking-[0.18em]\" style={{ color: C.muted }}>\n                      {s.label}\n                    </div>\n                  </div>\n                ))}\n              </div>\n            )}\n          </div>\n        </div>\n\n        {/* Radar in the flow on tablets and phones */}\n        <div className=\"mx-auto mt-12 w-[300px] lg:hidden\" style={{ pointerEvents: \"none\" }}>\n          <RadarScope uid=\"hero-m\" leaders={leaders} decorative />\n        </div>\n      </div>\n    </section>\n  );\n}\n",
 "components/home/FactsStrip.tsx": "\"use client\";\n\nimport { C } from \"@/lib/theme\";\nimport { useLanguage } from \"@/lib/i18n/LanguageContext\";\nimport { HOME_TEXT } from \"./homeText\";\n\nexport default function FactsStrip() {\n  const { locale } = useLanguage();\n  const text = HOME_TEXT[locale === \"ar\" ? \"ar\" : \"en\"];\n\n  return (\n    <div className=\"px-6 md:px-16\" style={{ background: C.panel, borderTop: `1px solid ${C.line}`, borderBottom: `1px solid ${C.line}` }}>\n      <ul\n        className=\"mx-auto flex max-w-[1312px] flex-wrap items-center justify-center gap-x-8 gap-y-3 py-5 text-xs uppercase tracking-[0.16em]\"\n        style={{ color: C.paper, minHeight: 68 }}\n      >\n        {text.facts.map((fact) => (\n          <li key={fact} className=\"inline-flex items-center gap-3.5 whitespace-nowrap\">\n            {fact}\n            <span aria-hidden=\"true\" className=\"inline-block h-1.5 w-1.5 rotate-45\" style={{ background: C.amber }} />\n          </li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n",
 "components/home/WaysIn.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { ArrowUpRight } from \"lucide-react\";\nimport { C } from \"@/lib/theme\";\nimport { useLanguage } from \"@/lib/i18n/LanguageContext\";\nimport { LadderArt, ReplayArt, BracketArt } from \"./PosterArt\";\nimport { HOME_TEXT } from \"./homeText\";\nimport \"@/app/cinematic.css\";\n\nconst CORNERS = [\n  \"top-2 left-2 border-t border-l\",\n  \"top-2 right-2 border-t border-r\",\n  \"bottom-2 left-2 border-b border-l\",\n  \"bottom-2 right-2 border-b border-r\",\n];\n\nexport default function WaysIn() {\n  const { locale } = useLanguage();\n  const text = HOME_TEXT[locale === \"ar\" ? \"ar\" : \"en\"];\n\n  const cards = [\n    { href: \"/leaderboard\", art: <LadderArt />, ...text.ways[0] },\n    { href: \"/replays\", art: <ReplayArt />, ...text.ways[1] },\n    { href: \"/tournaments\", art: <BracketArt />, ...text.ways[2] },\n  ];\n\n  return (\n    <section className=\"px-6 pb-10 pt-20 md:px-16 md:pt-24\">\n      <div className=\"mx-auto max-w-[1312px]\">\n        <div className=\"text-[11px] uppercase tracking-[0.24em]\" style={{ color: C.radar }}>\n          {text.waysEyebrow}\n        </div>\n        <h2 className=\"cz-display mb-9 mt-2 uppercase\" style={{ fontSize: \"clamp(48px, 6vw, 76px)\", fontWeight: 700, lineHeight: 1, color: C.paper }}>\n          {text.waysTitle}\n        </h2>\n\n        <div className=\"grid gap-6\" style={{ gridTemplateColumns: \"repeat(auto-fit, minmax(min(340px, 100%), 1fr))\" }}>\n          {cards.map((card) => (\n            <Link\n              key={card.href}\n              href={card.href}\n              className=\"cz-card cz-poster group relative block\"\n              style={{ background: C.panel, border: `1px solid ${C.line}`, color: C.paper }}\n            >\n              {CORNERS.map((pos) => (\n                <span\n                  key={pos}\n                  aria-hidden=\"true\"\n                  className={`pointer-events-none absolute z-[2] h-3 w-3 opacity-0 transition-opacity duration-300 group-hover:opacity-100 ${pos}`}\n                  style={{ borderColor: C.amber }}\n                />\n              ))}\n\n              <div className=\"relative overflow-hidden\" style={{ aspectRatio: \"4 / 3\", borderBottom: `1px solid ${C.line}` }}>\n                <div className=\"cz-poster-art absolute inset-0\">{card.art}</div>\n                <div aria-hidden=\"true\" className=\"absolute inset-0\" style={{ background: `linear-gradient(180deg, rgba(18,21,14,0) 55%, ${C.panel} 100%)` }} />\n                <span\n                  aria-hidden=\"true\"\n                  className=\"cz-display absolute bottom-1 start-5\"\n                  style={{ fontSize: 84, fontWeight: 700, lineHeight: 1, color: C.amber }}\n                >\n                  {card.n}\n                </span>\n              </div>\n\n              <div className=\"px-6 pb-7 pt-5\">\n                <h3 className=\"cz-display uppercase\" style={{ fontSize: 32, fontWeight: 600, color: C.paper }}>\n                  {card.title}\n                </h3>\n                <p className=\"mb-4 mt-2 text-sm leading-relaxed\" style={{ color: C.muted }}>\n                  {card.desc}\n                </p>\n                <span className=\"inline-flex min-h-[44px] items-center gap-2 text-xs font-bold uppercase tracking-[0.14em]\" style={{ color: C.amber }}>\n                  {card.cta}\n                  <ArrowUpRight size={14} strokeWidth={2.5} />\n                </span>\n              </div>\n            </Link>\n          ))}\n        </div>\n      </div>\n    </section>\n  );\n}\n",
 "components/home/FrontLine.tsx": "\"use client\";\n\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport { Medal, Trophy } from \"lucide-react\";\nimport { C } from \"@/lib/theme\";\nimport { useLanguage } from \"@/lib/i18n/LanguageContext\";\nimport { HOME_TEXT } from \"./homeText\";\nimport type { HomeData, Leader } from \"./useHomeData\";\nimport \"@/app/cinematic.css\";\n\nconst METAL: Record<number, string> = { 1: \"#E8A63D\", 2: \"#C0C0C0\", 3: \"#CD7F32\" };\n\nfunction PodiumCard({ leader, rank }: { leader: Leader; rank: 1 | 2 | 3 }) {\n  const first = rank === 1;\n  const color = METAL[rank];\n  const Icon = first ? Trophy : Medal;\n  const avatar = first ? 96 : 76;\n  const orderClass = rank === 1 ? \"order-1 md:order-2\" : rank === 2 ? \"order-2 md:order-1\" : \"order-3\";\n\n  return (\n    <Link\n      href={`/profile/${encodeURIComponent(leader.name)}`}\n      className={`cz-podium-link relative flex flex-1 flex-col items-center justify-end overflow-hidden px-6 pb-8 pt-8 text-center ${orderClass} ${first ? \"md:min-h-[580px]\" : \"md:min-h-[470px]\"}`}\n      style={{\n        flexBasis: 300,\n        background: first ? `linear-gradient(180deg, rgba(232,166,61,0.16), ${C.panel} 70%)` : C.panel,\n        border: `1px solid ${first ? C.amber : C.line}`,\n        boxShadow: first ? \"0 0 60px rgba(232,166,61,0.14)\" : undefined,\n        color: C.paper,\n      }}\n    >\n      <span\n        aria-hidden=\"true\"\n        className=\"cz-display absolute inset-x-0\"\n        style={{ bottom: -30, fontSize: 300, fontWeight: 700, lineHeight: 1, color: \"transparent\", WebkitTextStroke: `2px ${color}`, opacity: 0.22 }}\n      >\n        {rank}\n      </span>\n\n      <div className=\"relative flex flex-col items-center gap-1.5\">\n        <span role=\"img\" aria-label={`#${rank}`} style={{ color, display: \"inline-flex\" }}>\n          <Icon size={first ? 44 : 36} strokeWidth={1.8} />\n        </span>\n        {/* eslint-disable-next-line @next/next/no-img-element */}\n        <img\n          src={leader.avatarUrl || \"/default-avatar.svg\"}\n          alt=\"\"\n          className=\"rounded-full object-cover\"\n          style={{ width: avatar, height: avatar, border: `2px solid ${color}` }}\n        />\n        <div className=\"cz-display mt-2 uppercase\" style={{ fontSize: first ? 46 : 38, fontWeight: 700, lineHeight: 1.05, color: C.paper }}>\n          {leader.name}\n        </div>\n        <div className=\"cz-display\" style={{ fontSize: first ? 104 : 80, fontWeight: 700, lineHeight: 1, color: C.amber }}>\n          {leader.rating}\n        </div>\n        <div className=\"text-xs uppercase tracking-[0.14em]\" style={{ color: C.muted }}>\n          {leader.wins}W · {leader.losses}L\n        </div>\n      </div>\n    </Link>\n  );\n}\n\nexport default function FrontLine({ data }: { data: HomeData }) {\n  const { locale } = useLanguage();\n  const text = HOME_TEXT[locale === \"ar\" ? \"ar\" : \"en\"];\n  const [view, setView] = useState<\"team\" | \"ffa\">(\"team\");\n\n  // Nothing ranked anywhere yet (e.g. right after a season reset): skip the section entirely.\n  if (!data.loaded || (data.teamTop.length === 0 && data.ffaTop.length === 0)) return null;\n\n  const list = view === \"team\" ? data.teamTop : data.ffaTop;\n\n  const tab = (active: boolean) => ({\n    minHeight: 44,\n    padding: \"0 20px\",\n    background: active ? C.amber : \"transparent\",\n    color: active ? C.void : C.paper,\n    border: `1px solid ${active ? C.amber : C.amberDim}`,\n    fontSize: 12,\n    fontWeight: active ? 700 : 400,\n    letterSpacing: \"0.1em\",\n    textTransform: \"uppercase\" as const,\n  });\n\n  return (\n    <section className=\"px-6 pb-24 pt-16 md:px-16\">\n      <div className=\"mx-auto max-w-[1312px]\">\n        <div className=\"flex flex-wrap items-end justify-between gap-4\">\n          <div>\n            <div className=\"text-[11px] uppercase tracking-[0.24em]\" style={{ color: C.radar }}>\n              {text.frontEyebrow}\n            </div>\n            <h2 className=\"cz-display mb-9 mt-2 uppercase\" style={{ fontSize: \"clamp(48px, 6vw, 76px)\", fontWeight: 700, lineHeight: 1, color: C.paper }}>\n              {text.frontTitle1}{\" \"}\n              <span style={{ color: \"transparent\", WebkitTextStroke: `2px ${C.amber}` }}>{text.frontTitle2}</span>\n            </h2>\n          </div>\n\n          <div className=\"mb-9 flex flex-wrap items-center gap-2\">\n            <button type=\"button\" aria-pressed={view === \"team\"} onClick={() => setView(\"team\")} style={tab(view === \"team\")}>\n              {text.team}\n            </button>\n            <button type=\"button\" aria-pressed={view === \"ffa\"} onClick={() => setView(\"ffa\")} style={tab(view === \"ffa\")}>\n              {text.ffa}\n            </button>\n            <Link href=\"/leaderboard\" className=\"inline-flex min-h-[44px] items-center px-3 text-xs uppercase tracking-[0.14em]\" style={{ color: C.amber }}>\n              {text.fullBoard} →\n            </Link>\n          </div>\n        </div>\n\n        {list.length === 0 ? (\n          <p className=\"py-10 text-sm\" style={{ color: C.muted }}>\n            {text.frontEmpty}\n          </p>\n        ) : (\n          <div className=\"flex flex-wrap items-end gap-5\">\n            {list.map((leader, i) => (\n              <PodiumCard key={leader.name} leader={leader} rank={(i + 1) as 1 | 2 | 3} />\n            ))}\n          </div>\n        )}\n      </div>\n    </section>\n  );\n}\n",
 "components/home/JoinBanner.tsx": "\"use client\";\n\nimport Link from \"next/link\";\nimport { ArrowUpRight } from \"lucide-react\";\nimport { C, DISCORD_URL } from \"@/lib/theme\";\nimport { useLanguage } from \"@/lib/i18n/LanguageContext\";\nimport RadarScope from \"./RadarScope\";\nimport { HOME_TEXT } from \"./homeText\";\nimport \"@/app/cinematic.css\";\n\nexport default function JoinBanner() {\n  const { locale } = useLanguage();\n  const text = HOME_TEXT[locale === \"ar\" ? \"ar\" : \"en\"];\n\n  return (\n    <section\n      className=\"relative overflow-hidden px-6 py-24 md:px-16 md:py-32\"\n      style={{\n        borderTop: `1px solid ${C.line}`,\n        background: `radial-gradient(ellipse 60% 90% at 50% 100%, rgba(232,166,61,0.20), transparent 70%), ${C.panel}`,\n      }}\n    >\n      <div\n        aria-hidden=\"true\"\n        className=\"pointer-events-none absolute left-1/2 top-1/2\"\n        style={{ width: \"min(900px, 140vw)\", transform: \"translate(-50%, -50%)\", opacity: 0.32 }}\n      >\n        <RadarScope uid=\"cta\" decorative />\n      </div>\n\n      <div className=\"relative mx-auto max-w-[1000px] text-center\">\n        <div className=\"text-xs uppercase tracking-[0.24em]\" style={{ color: C.radar }}>\n          {text.joinEyebrow}\n        </div>\n        <h2 className=\"cz-display mt-3 uppercase\" style={{ fontSize: \"clamp(64px, 11vw, 150px)\", fontWeight: 700, lineHeight: 0.9, color: C.paper }}>\n          {text.joinTitle1}\n          <br />\n          <span style={{ color: C.amber }}>{text.joinTitle2}</span>\n        </h2>\n        <p className=\"mx-auto mt-6 max-w-[520px] text-base leading-relaxed\" style={{ color: C.paper }}>\n          {text.joinText}\n        </p>\n        <div className=\"mt-8 flex flex-wrap justify-center gap-3.5\">\n          <Link\n            href=\"/join\"\n            className=\"inline-flex min-h-[58px] items-center gap-2.5 px-9 text-sm font-bold uppercase tracking-[0.12em]\"\n            style={{ background: C.amber, color: C.void, boxShadow: \"0 0 34px rgba(232,166,61,0.32)\" }}\n          >\n            {text.apply}\n            <ArrowUpRight size={16} strokeWidth={2.5} />\n          </Link>\n          <a\n            href={DISCORD_URL}\n            target=\"_blank\"\n            rel=\"noopener noreferrer\"\n            className=\"inline-flex min-h-[58px] items-center px-8 text-sm font-semibold uppercase tracking-[0.12em]\"\n            style={{ border: `1px solid ${C.amberDim}`, color: C.amber }}\n          >\n            {text.discord}\n          </a>\n        </div>\n      </div>\n    </section>\n  );\n}\n"
};
const CHECKS = {
 "components/home/homeText.ts": {
  "startsWith": "// All new homepage copy",
  "noJsx": true,
  "mustContain": "heroTag"
 },
 "components/home/useHomeData.ts": {
  "startsWith": "\"use client\"",
  "noJsx": true,
  "mustContain": "export function useHomeData"
 },
 "components/home/RadarScope.tsx": {
  "startsWith": "\"use client\"",
  "noJsx": false,
  "mustContain": "function contourPath"
 },
 "components/home/PosterArt.tsx": {
  "startsWith": "import { C }",
  "noJsx": false,
  "mustContain": "export function LadderArt"
 },
 "components/home/CinematicHero.tsx": {
  "startsWith": "\"use client\"",
  "noJsx": false,
  "mustContain": "/images/banner.png"
 },
 "components/home/FactsStrip.tsx": {
  "startsWith": "\"use client\"",
  "noJsx": false,
  "mustContain": "export default function FactsStrip"
 },
 "components/home/WaysIn.tsx": {
  "startsWith": "\"use client\"",
  "noJsx": false,
  "mustContain": "export default function WaysIn"
 },
 "components/home/FrontLine.tsx": {
  "startsWith": "\"use client\"",
  "noJsx": false,
  "mustContain": "export default function FrontLine"
 },
 "components/home/JoinBanner.tsx": {
  "startsWith": "\"use client\"",
  "noJsx": false,
  "mustContain": "export default function JoinBanner"
 },
 "app/page.tsx": {
  "startsWith": "\"use client\"",
  "noJsx": false,
  "mustContain": "export default function Home"
 },
 "app/cinematic.css": {
  "startsWith": "/* Cinematic homepage",
  "noJsx": true,
  "mustContain": "@keyframes cz-sweep"
 }
};

// 1) Back up the current homepage once (never overwrites an existing backup).
const pagePath = path.join(root, "app", "page.tsx");
const backupPath = path.join(root, "app", "page.tsx.bak");
if (fs.existsSync(pagePath) && !fs.existsSync(backupPath)) {
  fs.copyFileSync(pagePath, backupPath);
  console.log("Backed up your current homepage to app/page.tsx.bak");
}

// 2) Write every file.
for (const [rel, content] of Object.entries(FILES)) {
  const full = path.join(root, rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, content, "utf8");
}

// 3) Read every file back and verify it is the right one.
let bad = 0;
console.log("");
for (const rel of Object.keys(FILES)) {
  const text = fs.readFileSync(path.join(root, rel), "utf8");
  const c = CHECKS[rel];
  const problems = [];
  if (!text.trimStart().startsWith(c.startsWith)) problems.push("wrong first line");
  if (!text.includes(c.mustContain)) problems.push("missing '" + c.mustContain + "'");
  if (c.noJsx && /<div|<section|<svg/.test(text)) problems.push("contains JSX that doesn't belong");
  const lines = text.split("\n").length;
  if (problems.length) bad++;
  console.log((problems.length ? "PROBLEM " : "ok      ") + rel.padEnd(38) + String(lines).padStart(4) + " lines" + (problems.length ? "  <- " + problems.join(", ") : ""));
}

console.log("");
if (bad) {
  console.log(bad + " file(s) failed the check. Copy this whole output and send it to Claude.");
  process.exit(1);
}
console.log("All 11 files installed and verified.");
console.log("Next: stop the dev server, delete the .next folder, then run: npm run dev");
console.log("To undo: copy app/page.tsx.bak back over app/page.tsx");
